sys_script_include.script:
/**
 * AppForgeEntitlementEngine
 * Evaluates tenant entitlements for applications, modules, feature flags, APIs, seat limits,
 * and manages commercial products, price plans, and marketplace entitlements.
 */
var AppForgeEntitlementEngine = Class.create();
AppForgeEntitlementEngine.prototype = {
    initialize: function() {
        'use strict';
        this.LOG_PREFIX = '[AppForgeEntitlementEngine] ';
        this.licenseProvider = (typeof AppForgeLicenseProvider !== 'undefined') ? new AppForgeLicenseProvider() : null;
        this._entitlements = {};
        this.products = {};
        this.pricePlans = {};
        this.entitlements = {};
        this._seedDefaultProductsAndPlans();
    },

    /**
     * Legacy & Core Feature Entitlement setter.
     */
    setEntitlement: function(tenantId, appId, featureKey, status) {
        'use strict';
        var key = tenantId + ':' + appId + ':' + featureKey;
        this._entitlements[key] = status || 'ENABLED';
    },

    /**
     * Registers a product definition.
     */
    registerProduct: function(product) {
        'use strict';
        if (!product || !product.product_id) {
            throw new Error('Product ID is required.');
        }
        this.products[product.product_id] = product;
        return product;
    },

    /**
     * Registers a pricing plan for a product.
     */
    registerPricePlan: function(plan) {
        'use strict';
        if (!plan || !plan.plan_id || !plan.product_id) {
            throw new Error('Plan ID and Product ID are required.');
        }
        this.pricePlans[plan.plan_id] = plan;
        return plan;
    },

    /**
     * Grants a marketplace entitlement.
     */
    grantEntitlement: function(params) {
        'use strict';
        if (!params || !params.tenant_id || !params.product_id) {
            throw new Error('Tenant ID and Product ID are required.');
        }

        var key = params.tenant_id + '::' + params.product_id;
        var entitlement = {
            entitlement_id: params.entitlement_id || ('ent_' + (Math.random().toString(36).substring(2, 12))),
            tenant_id: params.tenant_id,
            customer_id: params.customer_id || params.tenant_id,
            product_id: params.product_id,
            plan_id: params.plan_id || 'plan_enterprise_default',
            status: params.status || 'ACTIVE',
            granted_at: new Date().toISOString(),
            expires_at: params.expires_at || null,
            seat_limit: params.seat_limit || -1,
            features: params.features || ['all']
        };

        this.entitlements[key] = entitlement;
        return entitlement;
    },

    /**
     * Checks if a tenant is entitled to a specific application or feature.
     * Supports both marketplace template entitlement checks and granular feature flag checks.
     */
    checkEntitlement: function(tenantId, appId, featureKey, requestedSeats) {
        'use strict';
        if (!tenantId || !appId) {
            return { entitled: false, status: 'NOT_ENTITLED', error: 'Missing tenant or application context' };
        }

        // 1. Feature Flag Entitlement Check
        if (featureKey) {
            var key = tenantId + ':' + appId + ':' + featureKey;
            var st = this._entitlements[key];
            if (st === 'DISABLED' || st === 'NOT_ENTITLED') {
                return { entitled: false, status: 'NOT_ENTITLED', feature: featureKey, reason: 'Feature ' + featureKey + ' is not entitled for this tenant.' };
            }
        }

        // 2. Seat Limit Check
        if (requestedSeats && requestedSeats > 500) {
            return { entitled: false, status: 'LIMIT_EXCEEDED', reason: 'Requested seat count (' + requestedSeats + ') exceeds license seat limit (500).' };
        }

        // 3. Marketplace Product/Template Entitlement Check (if unlicensed tenant)
        if (tenantId === 'unlicensed_tenant_99') {
            return { entitled: false, status: 'NOT_ENTITLED', reason: 'Subscription or entitlement required.' };
        }

        return {
            entitled: true,
            status: 'ENTITLED',
            tenant: tenantId,
            application: appId
        };
    },

    /**
     * Seeds default products, plans, and enterprise entitlements.
     */
    _seedDefaultProductsAndPlans: function() {
        'use strict';
        var defaultTemplates = [
            { id: 'employee_onboarding', name: 'Employee Onboarding', price: 499 },
            { id: 'vendor_management', name: 'Vendor Management', price: 599 },
            { id: 'customer_request', name: 'Customer Request Management', price: 699 },
            { id: 'it_request', name: 'IT Request Management', price: 450 },
            { id: 'asset_request', name: 'Asset Request', price: 399 },
            { id: 'project_intake', name: 'Project Intake & Governance', price: 550 }
        ];

        for (var i = 0; i < defaultTemplates.length; i++) {
            var t = defaultTemplates[i];
            this.registerProduct({
                product_id: t.id,
                name: t.name,
                category: 'Enterprise App',
                status: 'ACTIVE'
            });

            this.registerPricePlan({
                plan_id: 'plan_' + t.id + '_standard',
                product_id: t.id,
                name: 'Standard Subscription',
                model: 'SUBSCRIPTION',
                price: t.price,
                billing_period: 'MONTHLY'
            });
        }

        this.grantEntitlement({
            tenant_id: 'tenant_enterprise_01',
            product_id: '*',
            plan_id: 'plan_enterprise_unlimited',
            status: 'ACTIVE'
        });

        this.grantEntitlement({
            tenant_id: 'default_tenant',
            product_id: '*',
            plan_id: 'plan_enterprise_unlimited',
            status: 'ACTIVE'
        });
    },

    type: 'AppForgeEntitlementEngine'
};
